 void refreshNetwork(){String connection="";try{ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);NetworkCapabilities n=cm.getNetworkCapabilities(cm.getActiveNetwork());connection=n==null?"":cm.getActiveNetwork().toString();vpnActive=false;int physical=0;for(Network candidate:cm.getAllNetworks()){NetworkCapabilities caps=cm.getNetworkCapabilities(candidate);if(caps==null)continue;if(caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN))vpnActive=true;else{if(caps.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET))physical|=1;if(caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI))physical|=2;}}vpnKnown=true;networkState=n==null?0:n.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)?2:1;networkTransport=n==null?0:n.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)?1:n.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?2:3;if(networkTransport==3&&n.hasTransport(NetworkCapabilities.TRANSPORT_VPN)&&(physical==1||physical==2))networkTransport=physical;network=networkTransport==0?"Нет сети":networkTransport==1?"LAN":networkTransport==2?"Wi-Fi":"Сеть · тип неизвестен";}catch(Exception e){vpnKnown=false;network="Неизвестно";networkState=1;networkTransport=3;}refreshWifiSignal();if(networkState==1)network+=" · интернет не подтверждён";if(speed!=null){speed.networkChanged(connection+":"+networkTransport+":"+vpnActive);updateSpeedFocus();}}
