 void fetchRates(){long now=SystemClock.elapsedRealtime();if(!active||ratesBusy||!ClockEstimate.due(now,ratesAttempt,300000))return;ratesAttempt=now;ratesBusy=true;new Thread(()->{try{if(System.currentTimeMillis()-prefs.getLong("fiat_at",0)>21600000){try{String[] r=RatesClient.fiat();prefs.edit().putString("USD",r[0]).putString("EUR",r[1]).putString("CNY",r[2]).putString("fiat_date",r[3]).putLong("fiat_at",System.currentTimeMillis()).apply();}catch(Exception ignored){}}if(active){try{double btc=RatesClient.bitcoin();prefs.edit().putString("BTC_USD",String.valueOf(btc)).putLong("btc_usd_at",System.currentTimeMillis()).apply();}catch(Exception ignored){}}}finally{if(active)fetchRateHistory();h.post(()->{ratesBusy=false;if(active)screen.invalidate();});}},"rates").start();}
 String historyKey(int i){return historyKey(i,RatesTrend.yesterday(System.currentTimeMillis()));}
 String historyKey(int i,String day){boolean cbr=i<3&&prefs.getString("fiat_date","").startsWith("ЦБ");return "history_"+new String[]{"USD","EUR","CNY","BTC_USD"}[i]+"_"+(cbr?"CBR":"Coinbase")+"_"+day;}
 void fetchRateHistory(){
  if(prefs.getInt("history_retry_version",0)<137){SharedPreferences.Editor retry=prefs.edit();for(String k:prefs.getAll().keySet())if(k.startsWith("attempt_history_")&&!prefs.contains(k.substring(8))||k.startsWith("history_attempt_CBR_"))retry.remove(k);retry.putInt("history_retry_version",137).apply();}
  long now=System.currentTimeMillis();int days=prefs.getBoolean("rates_chart",true)?6:1;
  boolean cbr=prefs.getString("fiat_date","").startsWith("ЦБ");
  for(int offset=0;offset<days&&active;offset++){
   if(offset>0&&!prefs.getBoolean("rates_chart",true))break;
   String day=RatesTrend.yesterday(now-offset*86400000L);
   boolean missing=false;for(int i=0;i<3;i++)if(!prefs.contains(historyKey(i,day)))missing=true;
   if(cbr&&missing&&ClockEstimate.due(now,prefs.getLong("history_attempt_CBR_"+day,-1),300000)){
    prefs.edit().putLong("history_attempt_CBR_"+day,now).apply();try{String[] date=day.split("-");String[] values=RatesClient.cbr("?date_req="+date[2]+"/"+date[1]+"/"+date[0]);SharedPreferences.Editor edit=prefs.edit();for(int i=0;i<3;i++)edit.putString("history_"+new String[]{"USD","EUR","CNY"}[i]+"_CBR_"+day,values[i]);edit.apply();}catch(Exception ignored){}
   }
   for(int i=cbr?3:0;i<4&&active;i++){
    String key=historyKey(i,day);if(prefs.contains(key)||!ClockEstimate.due(now,prefs.getLong("attempt_"+key,-1),300000))continue;
    prefs.edit().putLong("attempt_"+key,now).apply();try{double value=RatesClient.previous(new String[]{"USD","EUR","CNY","BTC"}[i],false,day);prefs.edit().putString(key,String.valueOf(value)).apply();}catch(Exception e){android.util.Log.w("ProskurninRates","History unavailable: "+new String[]{"USD","EUR","CNY","BTC"}[i]+" "+day+" "+e.getClass().getSimpleName());}
   }
  }
  String cutoff=RatesTrend.yesterday(now-7L*86400000);SharedPreferences.Editor edit=prefs.edit();for(String key:prefs.getAll().keySet())if((key.startsWith("history_")||key.startsWith("attempt_history_"))&&key.length()>10&&key.substring(key.length()-10).compareTo(cutoff)<0)edit.remove(key);edit.apply();
 }

 void updateTime(){Date now=new Date(System.currentTimeMillis());SimpleDateFormat f=new SimpleDateFormat(prefs.getBoolean("clock24",true)?"HH:mm":"h:mm a",new Locale("ru"));clock=f.format(now);date=new SimpleDateFormat("EEEE, d MMMM",new Locale("ru")).format(now);}
 void loadBackground(){if(!prefs.getBoolean("background",true)||!prefs.getBoolean("design",true)){bg=null;previousBg=null;period="";return;}Calendar cal=Calendar.getInstance();int hour=cal.get(Calendar.HOUR_OF_DAY);String p=hour<6||hour>=22?"night":hour<11?"morning":hour<17?"day":"evening";if(p.equals(period))return;period=p;final String chosenPeriod=p;final int token=++generation;new Thread(()->{Bitmap result=null;try(InputStream in=getAssets().open("backgrounds/"+chosenPeriod+".jpg")){BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=2;result=BitmapFactory.decodeStream(in,null,o);}catch(Exception|OutOfMemoryError e){}final Bitmap ready=result;h.post(()->{if(active&&token==generation){previousBg=bg;backgroundFade=SystemClock.elapsedRealtime();bg=ready;screen.invalidate();}});}).start();}
 void fetchWeather(){if(!active||weatherBusy||!ClockEstimate.due(SystemClock.elapsedRealtime(),weatherAt,weatherInterval))return;weatherBusy=true;weatherAt=SystemClock.elapsedRealtime();final int token=weatherGeneration;new Thread(()->{WeatherClient.Result result=null;try{result=WeatherClient.fetch(new File(getFilesDir(),"weather-routing.json"),prefs.getBoolean("weather_server",true),()->active);}catch(Exception ignored){}final WeatherClient.Result ready=result;h.post(()->{weatherBusy=false;if(token!=weatherGeneration){weatherAt=-1;if(active)fetchWeather();return;}if(ready!=null){weatherCached=ready.stale;prefs.edit().putString("weather_value",ready.text).putInt("weather_kind",ready.kind).putBoolean("weather_night",ready.night).putString("weather_wind",String.valueOf(ready.wind)).putLong("weather_time",System.currentTimeMillis()).putLong("weather_observed_at",ready.observedAt).putLong("weather_received_at",ready.receivedAt).apply();weather=ready.text;weatherInterval=1800000;android.util.Log.i("ProskurninWeather","Updated via "+ready.source);}else{weatherCached=true;weatherInterval=300000;weather=cachedWeather();if(!active)weatherAt=-1;}if(active)screen.invalidate();});},"weather").start();}
