 void settings(){
  ArrayList<String> items=new ArrayList<>(Arrays.asList("Новое оформление: "+(prefs.getBoolean("design",true)?"вкл":"выкл"),"Фон по времени суток: "+(prefs.getBoolean("background",true)?"вкл":"выкл"),"Часы: "+(prefs.getBoolean("clock24",true)?"24 часа":"12 часов"),"Открыть прежний главный экран"));
  if(!nativeHome()){items.add("Резервный автозапуск: "+(prefs.getBoolean("boot_home",true)?"вкл":"выкл"));items.add("Обработка кнопки Home");}
  final int chartIndex=items.size();items.add("Графики валют за 7 дней: "+(prefs.getBoolean("rates_chart",true)?"вкл":"выкл"));
  final int tintIndex=items.size();items.add("Цветные подложки приложений: "+(prefs.getBoolean("app_tints",true)?"вкл":"выкл"));
  new LauncherDialogs.Builder(this).setCustomTitle(versionTitle("Оформление экрана")).setItems(items.toArray(new String[0]),(d,n)->{
   if(n==tintIndex){prefs.edit().putBoolean("app_tints",!prefs.getBoolean("app_tints",true)).apply();screen.invalidate();return;}
   if(n==chartIndex){boolean on=!prefs.getBoolean("rates_chart",true);prefs.edit().putBoolean("rates_chart",on).apply();if(on){SharedPreferences.Editor retry=prefs.edit();for(String k:prefs.getAll().keySet())if(k.startsWith("attempt_history_")&&!prefs.contains(k.substring(8))||k.startsWith("history_attempt_CBR_"))retry.remove(k);retry.apply();ratesAttempt=0;fetchRates();}screen.invalidate();return;}
   if(n==3){openIntent(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(new ComponentName("com.google.android.tvlauncher","com.google.android.tvlauncher.MainActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return;}
   if(n==4){prefs.edit().putBoolean("boot_home",!prefs.getBoolean("boot_home",true)).apply();return;}
   if(n==5){openIntent(new Intent("android.settings.ACCESSIBILITY_SETTINGS"));return;}
   String key=n==0?"design":n==1?"background":"clock24";prefs.edit().putBoolean(key,!prefs.getBoolean(key,true)).apply();generation++;period="";updateTime();loadBackground();screen.invalidate();
  }).setNegativeButton("Закрыть",null).show();
 }

 public boolean onKeyDown(int code,KeyEvent e){
  if(code==KeyEvent.KEYCODE_MENU){if(e.getRepeatCount()==0&&!moving)settings();return true;}
  if(code==23||code==66){if(e.getRepeatCount()==0){longPress=false;confirmDown=true;e.startTracking();}return true;}
  if(code==4&&(drawer||moving)){backToApps();return true;}
  if(code>=19&&code<=22){
   if(moving){ArrayList<String> list=drawer?(inOther?arrangement.other:arrangement.apps):arrangement.home;int index=drawer?extraIndex:selected;int moved=AppArrangement.reorder(list,index,code);if(drawer)extraIndex=moved;else selected=moved;refreshFavoriteVisuals();}
   else if(drawer){if(code==19&&extraIndex<6){backToApps();}else extraIndex=AppArrangement.next(extraIndex,extras.size(),code,6);}
   else if(top){if(code==21)topIndex=Math.max(0,topIndex-1);if(code==22)topIndex=Math.min(quickCount()-1,topIndex+1);if(code==20)top=false;}
   else{if(code==21)selected=Math.max(0,selected-1);if(code==22)selected=Math.max(0,Math.min(pkgs.length-1,selected+1));if(code==19){top=true;topIndex=Math.min(quickCount()-1,selected*quickCount()/Math.max(1,pkgs.length));}if(code==20){drawer=true;inOther=false;rebuildExtras();extraIndex=Math.max(0,Math.min(selected,extras.size()-1));}}
   updateSpeedFocus();screen.invalidate();return true;
  }
  return super.onKeyDown(code,e);
 }
 public boolean onKeyLongPress(int code,KeyEvent e){if(code==23||code==66){longPress=true;confirmDown=false;if(moving)return true;if(!top||drawer)appMenu(focusedPackage());else if(quickAction(topIndex)==5)startActivity(new Intent(this,AssistantActivity.class));else settings();return true;}return super.onKeyLongPress(code,e);}
 public boolean onKeyUp(int code,KeyEvent e){if(code==23||code==66){boolean startedHere=confirmDown;confirmDown=false;if(startedHere&&!longPress&&!e.isCanceled()){if(moving)finishMove(true);else if(top&&!drawer)quick();else launch();}return true;}return super.onKeyUp(code,e);}
